<aside class="lab-card"><h2>Live laboratory data</h2><div class="readings"><div class="reading">Burette reading<strong><span id="reading">0.00</span> mL</strong></div><div class="reading">Volume delivered<strong><span id="delivered">0.00</span> mL</strong></div><div class="reading">Indicator<strong id="indicatorState">Not added</strong></div><div class="reading">Endpoint<strong id="endpointState">Not reached</strong></div></div><hr><h3>Practical procedure</h3><div id="steps"><div class="step active">1. Rinse and prepare the pipette</div><div class="step">2. Transfer measured acid to the conical flask</div><div class="step">3. Add a suitable indicator</div><div class="step">4. Rinse, fill and prepare the burette</div><div class="step">5. Record the initial burette reading</div><div class="step">6. Titrate while swirling</div><div class="step">7. Stop at the first permanent faint endpoint colour</div></div><h3>Calculation</h3><div class="formula-box">C₁V₁ = C₂V₂<br><br>HCl = 0.100 M<br>HCl volume = 25.00 mL<br>NaOH = 0.100 M<br><b>Expected equivalence ≈ 25.00 mL</b></div><p class="warning">Real practical skill matters: approaching the endpoint too quickly can overshoot it. The simulation records technique and changes the result accordingly.</p></aside>
</div>
<script>
const lab={step:1,reading:0,initial:null,rinsed:false,acid:false,indicator:false,filled:false,running:null,overshot:false};
const $=id=>document.getElementById(id);
function msg(t){$('status').textContent=t}
function render(){ $('reading').textContent=lab.reading.toFixed(2); $('delivered').textContent=(lab.initial===null?0:Math.max(0,lab.reading-lab.initial)).toFixed(2); $('buretteLiquid').style.height=Math.max(5,100-(lab.reading/50*100))+'%'; $('indicatorState').textContent=lab.indicator?'Phenolphthalein':'Not added'; $('endpointState').textContent=lab.overshot?'Overshot — invalid titre':(lab.reading>=24.98?'Reached — permanent faint pink':'Not reached'); $('solution').className='solution '+(lab.overshot?'overshot':(lab.reading>=24.98?'endpoint':'')); document.querySelectorAll('.step').forEach((x,i)=>x.classList.toggle('active',i+1===lab.step));}
function labAction(a){
 if(a==='reset'){if(lab.running)clearInterval(lab.running);Object.assign(lab,{step:1,reading:0,initial:null,rinsed:false,acid:false,indicator:false,filled:false,running:null,overshot:false});msg('Laboratory reset. Begin with the pipette.');render();return}
 if(a==='rinse'){lab.rinsed=true;lab.step=2;msg('Pipette rinsed. In a real lab the rinse liquid would be discarded before taking the measured sample.');render();return}
 if(a==='pipette'){if(!lab.rinsed){msg('Technique error: rinse the pipette first.');return}lab.acid=true;lab.step=3;msg('25.00 mL HCl transferred to the conical flask. The flask now contains the measured sample.');render();return}
 if(a==='indicator'){if(!lab.acid){msg('You need the acid sample in the flask first.');return}lab.indicator=true;lab.step=4;msg('A small amount of phenolphthalein has been added. The solution remains colourless in acidic conditions.');render();return}
 if(a==='fill'){if(!lab.indicator){msg('Prepare the flask before continuing.');return}lab.filled=true;lab.reading=0;lab.step=5;msg('Burette filled with 0.100 M NaOH. The scale is ready for the initial reading.');render();return}
 if(a==='initial'){if(!lab.filled){msg('Fill the burette first.');return}lab.initial=lab.reading;lab.step=6;msg('Initial burette reading recorded. Begin with a controlled addition and swirl the flask.');render();return}
 if(a==='swirl'){$('swirl').classList.toggle('swirling');msg('The conical flask is being swirled so incoming titrant mixes throughout the solution.');return}
 if(a==='stop'){if(lab.running){clearInterval(lab.running);lab.running=null;msg('Stopcock closed. Reading recorded at '+lab.reading.toFixed(2)+' mL.');render()}return}
 if(a==='fast'){if(lab.initial===null){msg('Record the initial burette reading first.');return}if(lab.running)return;lab.running=setInterval(()=>{let near=lab.reading>=22;if(near){lab.reading+=0.05}else{lab.reading+=0.25}let d=$('drop');d.classList.remove('fall');void d.offsetWidth;d.classList.add('fall');if(lab.reading>=24.8)lab.step=7;if(lab.reading>=25.25){lab.overshot=true;clearInterval(lab.running);lab.running=null;msg('Overshot endpoint. The colour has become too intense. Repeat the titration more carefully.')}else if(lab.reading>=24.98){clearInterval(lab.running);lab.running=null;msg('Endpoint reached: a faint pink colour persists after swirling. Stopcock closed automatically at the endpoint.')}render()},260);}
}
render();
</script>
